const raw = $input.first().json;
const body = raw.body || raw;

const event = String(body.event || '').toLowerCase().replace(/_/g, '.');
if (event === 'messages.set' || event === 'chats.set' || event === 'chats.upsert') {
  return [];
}
if (event && event !== 'messages.upsert') {
  return [];
}

const data = body.data || body;
const upsertType = String(data?.type || 'notify').toLowerCase();
if (upsertType === 'append') {
  return [];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.seen) staticData.seen = {};
const now = Date.now();
for (const [id, ts] of Object.entries(staticData.seen)) {
  if (now - ts > 5 * 60 * 1000) delete staticData.seen[id];
}

function extractText(msg) {
  if (!msg || typeof msg !== 'object') return '';
  if (msg.conversation) return String(msg.conversation);
  if (msg.extendedTextMessage?.text) return String(msg.extendedTextMessage.text);
  if (msg.imageMessage?.caption) return String(msg.imageMessage.caption);
  if (msg.videoMessage?.caption) return String(msg.videoMessage.caption);
  if (msg.buttonsResponseMessage?.selectedDisplayText) {
    return String(msg.buttonsResponseMessage.selectedDisplayText);
  }
  if (msg.listResponseMessage?.title) return String(msg.listResponseMessage.title);
  if (msg.ephemeralMessage?.message) return extractText(msg.ephemeralMessage.message);
  if (msg.viewOnceMessage?.message) return extractText(msg.viewOnceMessage.message);
  if (msg.documentWithCaptionMessage?.message) {
    return extractText(msg.documentWithCaptionMessage.message);
  }
  return '';
}

function processEntry(entry) {
  if (!entry?.key) return null;
  if (entry.key.fromMe === true) return null;

  const msgId = String(entry.key.id || '');
  if (msgId && staticData.seen[msgId]) return null;
  if (msgId) staticData.seen[msgId] = now;

  const jid = String(entry.key.remoteJid || '');
  if (!jid || jid.endsWith('@g.us') || jid === 'status@broadcast') return null;

  const phone = String(
    entry.key.remoteJidAlt ||
    entry.key.senderPn ||
    entry.key.participant ||
    jid
  )
    .replace('@s.whatsapp.net', '')
    .replace('@c.us', '')
    .split('@')[0]
    .replace(/\D/g, '');

  const text = extractText(entry.message).trim();
  if (phone && text) return { phone, text, messageId: msgId };
  return null;
}

let entries = [];
if (Array.isArray(data)) {
  entries = data;
} else if (Array.isArray(data?.messages)) {
  entries = data.messages;
} else if (data?.key) {
  entries = [data];
}

const out = [];
for (const entry of entries) {
  const row = processEntry(entry);
  const lower = row.text.toLowerCase();
  let intent = 'HELP';
  let product = '';
  if (/vend|venta|factur|entr[oó]|vendi/.test(lower)) intent = 'SALES';
  else if (/stock|inventario|quedan|cu[aá]nto.*tengo/.test(lower)) {
    intent = 'STOCK';
    const m = lower.match(/(?:de|tengo)\s+(.+)/);
    product = m ? m[1].trim() : '';
  } else if (/resumen|negocio|c[oó]mo est/.test(lower)) intent = 'SUMMARY';
  out.push({ json: { ...row, intent, product } });
}

return out;

const item = $input.first().json;
const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
if (!url || !key) throw new Error('Faltan SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY');
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: `${url}/rest/v1/rpc/fn_is_authorized`,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: { p_phone: item.phone },
  json: true,
});
// Sin respuesta a números no autorizados — silencio total
if (result !== true) return [];
return [{ json: item }];

const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const rows = await this.helpers.httpRequest({
  method: 'POST',
  url: `${url}/rest/v1/rpc/fn_get_sales`,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: { p_period: 'today' },
  json: true,
});
return [{ json: { rows: Array.isArray(rows) ? rows : [rows] } }];

const product = $('Verificar autorizado').first().json.product || null;
const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const rows = await this.helpers.httpRequest({
  method: 'POST',
  url: `${url}/rest/v1/rpc/fn_get_stock`,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: { p_product_name: product },
  json: true,
});
return [{ json: { rows: Array.isArray(rows) ? rows : [rows] } }];

const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const data = await this.helpers.httpRequest({
  method: 'POST',
  url: `${url}/rest/v1/rpc/fn_business_summary`,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: {},
  json: true,
});
const summary = Array.isArray(data) ? (data[0] || {}) : (data || {});
return [{ json: { summary } }];

const phone = $('Verificar autorizado').first().json.phone;
const intent = $('Verificar autorizado').first().json.intent;
const payload = $input.first().json;
let reply = '';

if (intent === 'SALES') {
  const rows = payload.rows || payload;
  const row = Array.isArray(rows) ? rows[0] : rows;
  const total = Number(row?.total || 0);
  const count = Number(row?.sales_count || 0);
  const avg = Number(row?.avg_sale || 0);
  reply = `Ventas de hoy\n\nTotal: $${total.toLocaleString('es-AR')}\nOperaciones: ${count}\nPromedio: $${avg.toLocaleString('es-AR')}`;
} else if (intent === 'STOCK') {
  const rows = payload.rows || payload;
  if (!Array.isArray(rows) || rows.length === 0) {
    reply = 'No encontré ese producto en el inventario.';
  } else if (rows.length === 1) {
    const p = rows[0];
    reply = `${p.name}\nStock: ${p.stock_current} u.\nMínimo: ${p.stock_minimum} u.`;
  } else {
    reply = 'Stock bajo / consulta:\n' + rows.slice(0, 8).map(p => `• ${p.name}: ${p.stock_current} u.`).join('\n');
  }
} else if (intent === 'SUMMARY') {
  const s = payload.summary || payload;
  reply = `Resumen del negocio\n\nVentas hoy: $${Number(s.sales_today||0).toLocaleString('es-AR')}\nOperaciones: ${s.sales_count||0}\nCríticos: ${s.critical_products||0}\nTop: ${s.top_product||'N/A'}\nGastos hoy: $${Number(s.expenses_today||0).toLocaleString('es-AR')}`;
} else {
  reply = 'Hola! Soy el asistente del kiosco.\n\nPodés preguntarme:\n• Cuánto vendí hoy\n• Stock de Coca Cola\n• Cómo está el negocio';
}

return [{ json: { phone, reply } }];

const phone = $input.first().json.phone;
const text = $input.first().json.reply;
if (!text) throw new Error('Sin texto de respuesta');
const apiKey = $env.EVOLUTION_API_KEY;
const instance = $env.EVOLUTION_INSTANCE || 'comercio-ia';
if (!apiKey) throw new Error('Falta EVOLUTION_API_KEY');
await this.helpers.httpRequest({
  method: 'POST',
  url: `http://evolution-api:8080/message/sendText/${instance}`,
  headers: { apikey: apiKey, 'Content-Type': 'application/json' },
  body: { number: phone, text },
  json: true,
});
return [{ json: { phone, text, sent: true } }];
